/**
 * INI reader and writer with quoted tokens, escape sequences and a configurable
 * duplicate-key policy. Parsing and serialising are exact inverses for every
 * document this module can produce.
 */

/** Failure raised by {@link parse} and {@link stringify}. */
export class IniError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [line] 1-based line number the failure was found on
   */
  constructor(message, line) {
    super(message);
    this.name = 'IniError';
    this.line = line;
  }
}

const DUPLICATE_POLICIES = new Set(['last', 'first', 'error', 'array']);

const ESCAPE_DECODE = new Map([
  ['\\', '\\'],
  ['"', '"'],
  ['n', '\n'],
  ['r', '\r'],
  ['t', '\t'],
  ['0', '\0'],
  [';', ';'],
  ['#', '#'],
  ['=', '='],
  ['[', '['],
  [']', ']'],
]);

const ESCAPE_ENCODE = new Map([
  ['\\', '\\\\'],
  ['"', '\\"'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
  ['\0', '\\0'],
]);

const VALUE_NEEDS_QUOTE = /["\\\n\r\t\0;#=]/;
const KEY_NEEDS_QUOTE = /["\\\n\r\t\0;#=[\]]/;
const SECTION_NEEDS_QUOTE = /["\\\n\r\t\0[\]]/;

/**
 * Store an own, enumerable property even when the key shadows something on
 * `Object.prototype`.
 *
 * @param {Record<string, unknown>} target container to write into
 * @param {string} key property name
 * @param {unknown} value property value
 * @returns {void}
 */
function setEntry(target, key, value) {
  Object.defineProperty(target, key, { value, writable: true, enumerable: true, configurable: true });
}

/**
 * Read one double-quoted token starting at `start`.
 *
 * @param {string} text line the token appears in
 * @param {number} start index of the opening quote
 * @param {number} line 1-based line number for error reporting
 * @returns {{ value: string, end: number }} decoded text and the index just past the closing quote
 */
function readQuoted(text, start, line) {
  let out = '';
  let i = start + 1;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '"') return { value: out, end: i + 1 };
    if (ch !== '\\') {
      out += ch;
      i += 1;
      continue;
    }
    const code = text[i + 1];
    if (code === undefined) throw new IniError('unterminated quoted string', line);
    if (code === 'u') {
      const hex = text.slice(i + 2, i + 6);
      if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw new IniError(`invalid unicode escape: \\u${hex}`, line);
      out += String.fromCharCode(Number.parseInt(hex, 16));
      i += 6;
      continue;
    }
    const decoded = ESCAPE_DECODE.get(code);
    if (decoded === undefined) throw new IniError(`unknown escape sequence: \\${code}`, line);
    out += decoded;
    i += 2;
  }
  throw new IniError('unterminated quoted string', line);
}

/**
 * Decode one token that may or may not be quoted.
 *
 * @param {string} token trimmed source text
 * @param {number} line 1-based line number for error reporting
 * @param {string} what noun used in the "unexpected text" message
 * @returns {string} decoded text
 */
function decodeToken(token, line, what) {
  if (!token.startsWith('"')) return token;
  const { value, end } = readQuoted(token, 0, line);
  if (token.slice(end).trim() !== '') throw new IniError(`unexpected text after quoted ${what}`, line);
  return value;
}

/**
 * Record one key/value pair under the active duplicate policy.
 *
 * @param {Record<string, unknown>} target section body to write into
 * @param {string} key decoded key
 * @param {string} value decoded value
 * @param {string} duplicates policy name
 * @param {number} line 1-based line number for error reporting
 * @returns {void}
 */
function assign(target, key, value, duplicates, line) {
  if (!Object.hasOwn(target, key)) {
    setEntry(target, key, value);
    return;
  }
  if (duplicates === 'last') setEntry(target, key, value);
  else if (duplicates === 'error') throw new IniError(`duplicate key: ${key}`, line);
  else if (duplicates === 'array') {
    const existing = target[key];
    setEntry(target, key, Array.isArray(existing) ? [...existing, value] : [existing, value]);
  }
}

/**
 * Parse an INI document.
 *
 * @param {string} text document source
 * @param {{ duplicates?: 'last' | 'first' | 'error' | 'array' }} [options] duplicate-key policy
 * @returns {{ global: Record<string, string | string[]>, sections: Record<string, Record<string, string | string[]>> }}
 *   keys seen before the first header, and one body per section header
 */
export function parse(text, options = {}) {
  if (typeof text !== 'string') throw new IniError('input must be a string');
  const duplicates = options.duplicates ?? 'last';
  if (!DUPLICATE_POLICIES.has(duplicates)) throw new IniError(`unknown duplicates policy: ${duplicates}`);

  const result = { global: {}, sections: {} };
  let current = result.global;
  const lines = text.split(/\r\n|\n|\r/);

  for (let i = 0; i < lines.length; i += 1) {
    const line = i + 1;
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed[0] === ';' || trimmed[0] === '#') continue;

    if (trimmed[0] === '[') {
      if (!trimmed.endsWith(']')) throw new IniError('unterminated section header', line);
      const name = decodeToken(trimmed.slice(1, -1).trim(), line, 'section name');
      if (name === '') throw new IniError('empty section name', line);
      if (!Object.hasOwn(result.sections, name)) setEntry(result.sections, name, {});
      current = result.sections[name];
      continue;
    }

    let key;
    let rest;
    if (trimmed[0] === '"') {
      const quoted = readQuoted(trimmed, 0, line);
      const after = trimmed.slice(quoted.end);
      const eq = after.indexOf('=');
      if (eq === -1) throw new IniError("missing '=' in entry", line);
      if (after.slice(0, eq).trim() !== '') throw new IniError('unexpected text after quoted key', line);
      key = quoted.value;
      rest = after.slice(eq + 1);
    } else {
      const eq = trimmed.indexOf('=');
      if (eq === -1) throw new IniError("missing '=' in entry", line);
      key = trimmed.slice(0, eq).trim();
      rest = trimmed.slice(eq + 1);
    }
    if (key === '') throw new IniError('empty key', line);
    assign(current, key, decodeToken(rest.trim(), line, 'value'), duplicates, line);
  }
  return result;
}

/**
 * Wrap text in double quotes, escaping the characters that cannot appear raw.
 *
 * @param {string} text text to quote
 * @returns {string} quoted token
 */
function quote(text) {
  let out = '"';
  for (const ch of text) out += ESCAPE_ENCODE.get(ch) ?? ch;
  return `${out}"`;
}

/**
 * Serialise one value as it would appear to the right of `=`.
 *
 * @param {string} value value text
 * @returns {string} quoted token when quoting is required, otherwise the value itself
 */
export function formatValue(value) {
  if (typeof value !== 'string') throw new IniError(`value must be a string, got ${typeof value}`);
  if (value === '' || value !== value.trim() || value.startsWith('[') || VALUE_NEEDS_QUOTE.test(value)) {
    return quote(value);
  }
  return value;
}

/**
 * Serialise one key as it would appear to the left of `=`.
 *
 * @param {string} key key text
 * @returns {string} quoted token when quoting is required, otherwise the key itself
 */
export function formatKey(key) {
  if (typeof key !== 'string') throw new IniError(`key must be a string, got ${typeof key}`);
  if (key === '') throw new IniError('empty key');
  if (key !== key.trim() || KEY_NEEDS_QUOTE.test(key)) return quote(key);
  return key;
}

/**
 * Serialise one section name including its brackets.
 *
 * @param {string} name section name
 * @returns {string} bracketed header text
 */
function formatSection(name) {
  if (name === '') throw new IniError('empty section name');
  const inner = name !== name.trim() || SECTION_NEEDS_QUOTE.test(name) ? quote(name) : name;
  return `[${inner}]`;
}

/**
 * Append the lines for one key, expanding arrays into repeated entries.
 *
 * @param {string[]} out accumulated output lines
 * @param {string} key key text
 * @param {string | string[]} value value or repeated values
 * @returns {void}
 */
function emit(out, key, value) {
  const token = formatKey(key);
  if (Array.isArray(value)) {
    for (const item of value) out.push(`${token}=${formatValue(item)}`);
    return;
  }
  out.push(`${token}=${formatValue(value)}`);
}

/**
 * Serialise a parsed document back to INI text.
 *
 * @param {{ global?: Record<string, string | string[]>, sections?: Record<string, Record<string, string | string[]>> }} data
 *   document to write
 * @param {{ eol?: string }} [options] line terminator, `'\n'` by default
 * @returns {string} INI text, empty when the document has no entries
 */
export function stringify(data, options = {}) {
  if (data === null || typeof data !== 'object') throw new IniError('document must be an object');
  const eol = options.eol ?? '\n';
  const global = data.global ?? {};
  const sections = data.sections ?? {};
  const out = [];

  for (const key of Object.keys(global)) emit(out, key, global[key]);
  for (const name of Object.keys(sections)) {
    if (out.length > 0) out.push('');
    out.push(formatSection(name));
    const body = sections[name];
    if (body === null || typeof body !== 'object') throw new IniError(`section body must be an object: ${name}`);
    for (const key of Object.keys(body)) emit(out, key, body[key]);
  }
  return out.length === 0 ? '' : out.join(eol) + eol;
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { IniError, formatKey, formatValue, parse, stringify } from '../src/ini.js';

/** Deterministic 32-bit PRNG so the generated cases are identical on every run. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function throws(fn) {
  try {
    fn();
  } catch (error) {
    return error;
  }
  throw new Error('expected the call to throw');
}

test('parses globals and sections', () => {
  const doc = parse('a=1\n[server]\nhost=localhost\nport=8080\n');
  assert.deepStrictEqual(doc.global, { a: '1' });
  assert.deepStrictEqual(doc.sections, { server: { host: 'localhost', port: '8080' } });
});

test('empty input yields an empty document', () => {
  assert.deepStrictEqual(parse(''), { global: {}, sections: {} });
  assert.deepStrictEqual(parse('\n\n   \n'), { global: {}, sections: {} });
});

test('comments are recognised only at the start of a trimmed line', () => {
  const doc = parse('; a comment\n   # another\nk=v ; not a comment\nj=v # neither\n');
  assert.deepStrictEqual(doc.global, { k: 'v ; not a comment', j: 'v # neither' });
});

test('whitespace around keys and values is stripped, quoted whitespace is kept', () => {
  const doc = parse('  key   =   value  \n pad = "  padded  "\n');
  assert.equal(doc.global.key, 'value');
  assert.equal(doc.global.pad, '  padded  ');
});

test('an unquoted value keeps interior characters verbatim', () => {
  const doc = parse('path=C:\\Users\\x\nempty=\nsymbols=a=b=c\n');
  assert.equal(doc.global.path, 'C:\\Users\\x');
  assert.equal(doc.global.empty, '');
  assert.equal(doc.global.symbols, 'a=b=c');
});

test('escape sequences are decoded inside quotes', () => {
  const doc = parse('a="x\\ny"\nb="\\t\\\\\\""\nc="\\0"\nd="\\;\\#\\=\\[\\]"\ne="caf\\u00e9"\n');
  assert.equal(doc.global.a, 'x\ny');
  assert.equal(doc.global.b, '\t\\"');
  assert.equal(doc.global.c, '\0');
  assert.equal(doc.global.d, ';#=[]');
  assert.equal(doc.global.e, 'café');
});

test('quoted keys and section names may contain separators', () => {
  const doc = parse('"a=b" = 1\n["x]y"]\n"k[0]"=2\n');
  assert.deepStrictEqual(doc.global, { 'a=b': '1' });
  assert.deepStrictEqual(doc.sections, { 'x]y': { 'k[0]': '2' } });
});

test('CRLF and lone CR terminate lines', () => {
  assert.deepStrictEqual(parse('a=1\r\nb=2\r\n').global, { a: '1', b: '2' });
  assert.deepStrictEqual(parse('a=1\rb=2').global, { a: '1', b: '2' });
});

test('astral characters survive parsing', () => {
  const doc = parse('emoji=a😀b\nquoted="😀\\t"\n');
  assert.equal(doc.global.emoji, 'a😀b');
  assert.equal(doc.global.quoted, '😀\t');
});

test('repeated section headers reuse the same body', () => {
  const doc = parse('[a]\nx=1\n[b]\ny=2\n[a]\nz=3\n');
  assert.deepStrictEqual(doc.sections, { a: { x: '1', z: '3' }, b: { y: '2' } });
  assert.deepStrictEqual(Object.keys(doc.sections), ['a', 'b']);
});

test('keys shadowing Object.prototype stay own properties', () => {
  const doc = parse('__proto__=x\n[constructor]\ntoString=y\n');
  assert.deepStrictEqual(doc.global, { ['__proto__']: 'x' });
  assert.equal(Object.getPrototypeOf(doc.global), Object.prototype);
  assert.equal(doc.sections.constructor.toString, 'y');
  assert.equal(stringify(doc), '__proto__=x\n\n[constructor]\ntoString=y\n');
});

test('duplicate keys follow the configured policy', () => {
  const text = '[s]\nk=1\nk=2\nk=3\n';
  assert.equal(parse(text).sections.s.k, '3');
  assert.equal(parse(text, { duplicates: 'last' }).sections.s.k, '3');
  assert.equal(parse(text, { duplicates: 'first' }).sections.s.k, '1');
  assert.deepStrictEqual(parse(text, { duplicates: 'array' }).sections.s.k, ['1', '2', '3']);
  const error = throws(() => parse(text, { duplicates: 'error' }));
  assert.equal(error.name, 'IniError');
  assert.equal(error.line, 4);
});

test('the array policy leaves single occurrences as strings', () => {
  const doc = parse('a=1\nb=2\nb=3\n', { duplicates: 'array' });
  assert.equal(doc.global.a, '1');
  assert.deepStrictEqual(doc.global.b, ['2', '3']);
});

test('the same key in different sections is not a duplicate', () => {
  const doc = parse('[a]\nk=1\n[b]\nk=2\n', { duplicates: 'error' });
  assert.deepStrictEqual(doc.sections, { a: { k: '1' }, b: { k: '2' } });
});

test('malformed documents report the reason and the line', () => {
  const cases = [
    ['a=1\n[unclosed\n', /unterminated section header/, 2],
    ['\n\nk\n', /missing '=' in entry/, 3],
    ['  =1\n', /empty key/, 1],
    ['[]\n', /empty section name/, 1],
    ['[  ]\n', /empty section name/, 1],
    ['a="oops\n', /unterminated quoted string/, 1],
    ['a="x\\\n', /unterminated quoted string/, 1],
    ['a="x\\q"\n', /unknown escape sequence: \\q/, 1],
    ['a="\\u12g4"\n', /invalid unicode escape/, 1],
    ['a="x" trailing\n', /unexpected text after quoted value/, 1],
    ['"k" oops = 1\n', /unexpected text after quoted key/, 1],
    ['"k"\n', /missing '=' in entry/, 1],
    ['["s" oops]\n', /unexpected text after quoted section name/, 1],
  ];
  for (const [text, pattern, line] of cases) {
    const error = throws(() => parse(text));
    assert.ok(error instanceof IniError, `expected IniError for ${JSON.stringify(text)}`);
    assert.match(error.message, pattern);
    assert.equal(error.line, line, `line for ${JSON.stringify(text)}`);
  }
});

test('non-string input and unknown policies are rejected', () => {
  assert.throws(() => parse(null), IniError);
  assert.throws(() => parse(['a=1']), IniError);
  assert.throws(() => parse('a=1', { duplicates: 'merge' }), /unknown duplicates policy: merge/);
});

test('formatValue quotes exactly the values that need it', () => {
  const cases = [
    ['plain', 'plain'],
    ['with space', 'with space'],
    ['', '""'],
    [' pad ', '" pad "'],
    ['a;b', '"a;b"'],
    ['a#b', '"a#b"'],
    ['a=b', '"a=b"'],
    ['[x]', '"[x]"'],
    ['x[1]', 'x[1]'],
    ['a"b', '"a\\"b"'],
    ['a\\b', '"a\\\\b"'],
    ['a\nb', '"a\\nb"'],
    ['a\tb', '"a\\tb"'],
    ['a\0b', '"a\\0b"'],
    ['😀', '😀'],
  ];
  for (const [value, expected] of cases) assert.equal(formatValue(value), expected, `formatValue(${JSON.stringify(value)})`);
});

test('formatKey quotes separators and bracket characters', () => {
  assert.equal(formatKey('plain'), 'plain');
  assert.equal(formatKey('a b'), 'a b');
  assert.equal(formatKey('a=b'), '"a=b"');
  assert.equal(formatKey('[a]'), '"[a]"');
  assert.equal(formatKey(' a'), '" a"');
  assert.equal(formatKey(';a'), '";a"');
});

test('stringify writes globals first and blank-line separated sections', () => {
  const text = stringify({ global: { a: '1' }, sections: { s: { b: '2' }, t: { c: '3' } } });
  assert.equal(text, 'a=1\n\n[s]\nb=2\n\n[t]\nc=3\n');
});

test('stringify handles missing halves, empty documents and the eol option', () => {
  assert.equal(stringify({}), '');
  assert.equal(stringify({ global: {}, sections: {} }), '');
  assert.equal(stringify({ sections: { s: {} } }), '[s]\n');
  assert.equal(stringify({ global: { a: '1' } }), 'a=1\n');
  assert.equal(stringify({ global: { a: '1' }, sections: { s: { b: '2' } } }, { eol: '\r\n' }), 'a=1\r\n\r\n[s]\r\nb=2\r\n');
});

test('stringify expands arrays into repeated entries', () => {
  assert.equal(stringify({ global: { k: ['1', '2'] } }), 'k=1\nk=2\n');
  assert.deepStrictEqual(parse(stringify({ global: { k: ['1', '2'] } }), { duplicates: 'array' }).global.k, ['1', '2']);
});

test('stringify rejects empty names and non-string values', () => {
  assert.throws(() => stringify({ global: { '': 'x' } }), /empty key/);
  assert.throws(() => stringify({ sections: { '': {} } }), /empty section name/);
  assert.throws(() => stringify({ global: { a: 1 } }), /value must be a string/);
  assert.throws(() => stringify({ global: { a: null } }), /value must be a string/);
  assert.throws(() => stringify(null), /document must be an object/);
});

test('a hand written document round-trips through both directions', () => {
  const doc = {
    global: { ' spaced ': 'v', 'a=b': ';#', '': undefined },
    sections: {},
  };
  delete doc.global[''];
  doc.sections['x]y'] = { 'k\n': 'line\nbreak', tab: '\t', empty: '' };
  const text = stringify(doc);
  assert.deepStrictEqual(parse(text), doc);
  assert.equal(stringify(parse(text)), text);
});

test('round-trip holds for generated documents', () => {
  const random = mulberry32(0x5eed);
  const alphabet = ['a', 'Z', '0', ' ', '=', ';', '#', '[', ']', '"', '\\', '\n', '\t', '\0', 'é', '😀', '\r'];
  const pick = (list) => list[Math.floor(random() * list.length)];
  const text = (min) => {
    const length = min + Math.floor(random() * 4);
    let out = '';
    for (let i = 0; i < length; i += 1) out += pick(alphabet);
    return out;
  };

  let checked = 0;
  for (let iteration = 0; iteration < 200; iteration += 1) {
    const doc = { global: {}, sections: {} };
    const globals = Math.floor(random() * 3);
    for (let i = 0; i < globals; i += 1) doc.global[text(1)] = text(0);
    const sections = Math.floor(random() * 3);
    for (let i = 0; i < sections; i += 1) {
      const body = {};
      const entries = Math.floor(random() * 3);
      for (let j = 0; j < entries; j += 1) body[text(1)] = text(0);
      doc.sections[text(1)] = body;
    }
    const serialised = stringify(doc);
    assert.deepStrictEqual(parse(serialised), doc, `round-trip failed for ${JSON.stringify(serialised)}`);
    assert.equal(stringify(parse(serialised)), serialised);
    checked += 1;
  }
  assert.equal(checked, 200);
});

test('generated values survive quoting in isolation', () => {
  const random = mulberry32(99);
  const alphabet = ['x', ' ', '"', '\\', '\n', '\r', '\t', '\0', ';', '#', '=', '[', ']', 'ß', '😀'];
  for (let i = 0; i < 150; i += 1) {
    let value = '';
    const length = Math.floor(random() * 5);
    for (let j = 0; j < length; j += 1) value += alphabet[Math.floor(random() * alphabet.length)];
    assert.equal(parse(`k=${formatValue(value)}`).global.k, value, `value ${JSON.stringify(value)}`);
  }
});

