#!/usr/bin/env node
/**
 * Validate every task directory beside this script.
 *
 * For each task: check `task.json`, run the test suite against the shipped
 * pre-state (which must fail), run it again with `src/` replaced by
 * `reference/src/` (which must pass), and check the size and dependency rules.
 */
import { execFileSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const MAX_BYTES = 150 * 1024;
const REQUIRED_CHECKS = [
  { id: 'tests-pass', outcome: 'the test suite passes', run: 'node --test test/*.test.js' },
  { id: 'no-dependencies', outcome: 'no packages were installed', run: 'test ! -e node_modules' },
];

const problems = [];

/**
 * Record a violation for the final exit status.
 *
 * @param {string} task task directory name
 * @param {string} message what is wrong
 * @returns {void}
 */
function fail(task, message) {
  problems.push(`${task}: ${message}`);
}

/**
 * List every file below a directory.
 *
 * @param {string} dir directory to walk
 * @returns {string[]} absolute file paths
 */
function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else out.push(full);
  }
  return out;
}

/**
 * Run one shell command in a directory.
 *
 * @param {string} command shell command line
 * @param {string} cwd working directory
 * @returns {number} exit status, 1 when the process was killed by a signal
 */
function run(command, cwd) {
  try {
    execFileSync('sh', ['-c', command], { cwd, stdio: 'pipe' });
    return 0;
  } catch (error) {
    return typeof error.status === 'number' ? error.status : 1;
  }
}

/**
 * Count assertion call sites in a task's test files.
 *
 * @param {string} taskDir task directory
 * @returns {number} number of `assert...(` call sites
 */
function countAssertions(taskDir) {
  let total = 0;
  for (const file of walk(path.join(taskDir, 'test'))) {
    const source = readFileSync(file, 'utf8');
    total += (source.match(/\bassert(?:\.[A-Za-z]+)?\s*\(/g) ?? []).length;
  }
  return total;
}

const tasks = readdirSync(root, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)
  .filter((name) => {
    try {
      return statSync(path.join(root, name, 'task.json')).isFile();
    } catch {
      return false;
    }
  })
  .sort();

if (tasks.length === 0) {
  console.error('no task directories found');
  process.exit(1);
}

for (const name of tasks) {
  const taskDir = path.join(root, name);
  let meta;
  try {
    meta = JSON.parse(readFileSync(path.join(taskDir, 'task.json'), 'utf8'));
  } catch (error) {
    fail(name, `task.json is not valid JSON: ${error.message}`);
    continue;
  }

  if (meta.id !== `code:${name}`) fail(name, `id must be "code:${name}", got ${JSON.stringify(meta.id)}`);
  if (![2, 3, 4].includes(meta.tier)) fail(name, `tier must be 2, 3 or 4, got ${JSON.stringify(meta.tier)}`);
  if (typeof meta.domain !== 'string' || meta.domain.length === 0) fail(name, 'domain must be a non-empty string');
  if (typeof meta.title !== 'string' || meta.title.length === 0) fail(name, 'title must be a non-empty string');
  if (typeof meta.prompt !== 'string' || meta.prompt.length < 200) fail(name, 'prompt must be a substantial string');
  if (typeof meta.heldOut !== 'boolean') fail(name, 'heldOut must be a boolean');
  if (JSON.stringify(meta.immutable) !== JSON.stringify(['test', 'package.json'])) {
    fail(name, 'immutable must be ["test", "package.json"]');
  }
  if (JSON.stringify(meta.checks) !== JSON.stringify(REQUIRED_CHECKS)) fail(name, 'checks do not match the required pair');
  for (const forbidden of ['tier', 'held out', 'held-out', 'heldOut', 'reference solution']) {
    if (meta.prompt.toLowerCase().includes(forbidden.toLowerCase())) fail(name, `prompt leaks "${forbidden}"`);
  }

  const pkgPath = path.join(taskDir, 'package.json');
  let pkg;
  try {
    pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
  } catch (error) {
    fail(name, `package.json is not valid JSON: ${error.message}`);
    continue;
  }
  if (pkg.name !== name || pkg.type !== 'module' || pkg.private !== true) fail(name, 'package.json header is wrong');
  if (pkg.scripts?.test !== 'node --test test/*.test.js') fail(name, 'package.json test script is wrong');
  if (pkg.dependencies || pkg.devDependencies) fail(name, 'package.json declares dependencies');

  const files = walk(taskDir);
  if (files.some((file) => file.includes(`${path.sep}node_modules${path.sep}`))) fail(name, 'node_modules is present');
  const bytes = files.reduce((sum, file) => sum + statSync(file).size, 0);
  if (bytes > MAX_BYTES) fail(name, `directory is ${bytes} bytes, over the ${MAX_BYTES} byte limit`);
  if (!files.some((file) => file.includes(`${path.sep}reference${path.sep}src${path.sep}`))) {
    fail(name, 'reference/src is missing');
  }
  if (!files.some((file) => file.startsWith(path.join(taskDir, 'src') + path.sep))) fail(name, 'src is missing');

  const workspace = mkdtempSync(path.join(tmpdir(), `pg-${name}-`));
  let preStatus = -1;
  let refStatus = -1;
  try {
    cpSync(taskDir, workspace, {
      recursive: true,
      filter: (source) => source !== path.join(taskDir, 'reference') && !source.startsWith(path.join(taskDir, 'reference') + path.sep),
    });
    preStatus = run('node --test test/*.test.js', workspace);
    rmSync(path.join(workspace, 'src'), { recursive: true, force: true });
    cpSync(path.join(taskDir, 'reference', 'src'), path.join(workspace, 'src'), { recursive: true });
    refStatus = run('node --test test/*.test.js', workspace);
  } finally {
    rmSync(workspace, { recursive: true, force: true });
  }

  if (preStatus === 0) fail(name, 'pre-state passes the test suite but must fail');
  if (refStatus !== 0) fail(name, `reference fails the test suite (exit ${refStatus})`);

  const assertions = countAssertions(taskDir);
  if (assertions < 25 || assertions > 60) fail(name, `assertion count ${assertions} is outside 25..60`);

  const preState = preStatus === 0 ? 'pass' : 'fail';
  const reference = refStatus === 0 ? 'pass' : 'fail';
  console.log(`${meta.id} tier=${meta.tier} preState=${preState} reference=${reference} assertions=${assertions} bytes=${bytes}`);
}

if (problems.length > 0) {
  console.error('\nvalidation failed:');
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}
console.log(`\nall ${tasks.length} tasks validated`);

