/** Lexical analysis for the arithmetic expression language. */

/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const PUNCTUATION = new Map([
  ['(', 'lparen'],
  [')', 'rparen'],
  [',', 'comma'],
]);
const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);
const WHITESPACE = new Set([' ', '\t', '\n', '\r', '\f', '\v']);
const NUMBER = /(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/y;
const NAME = /[A-Za-z_][A-Za-z0-9_]*/y;
const NUMBER_TAIL = /[.\dA-Za-z_]/;

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  if (typeof input !== 'string') throw new ExprError('input must be a string at 0', 0);
  const tokens = [];
  let i = 0;
  while (i < input.length) {
    const ch = input[i];
    if (WHITESPACE.has(ch)) {
      i += 1;
      continue;
    }
    const punctuation = PUNCTUATION.get(ch);
    if (punctuation !== undefined) {
      tokens.push({ type: punctuation, value: ch, index: i });
      i += 1;
      continue;
    }
    if (OPERATORS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }
    if ((ch >= '0' && ch <= '9') || ch === '.') {
      NUMBER.lastIndex = i;
      const matched = NUMBER.exec(input);
      const tail = matched === null ? ch : input[i + matched[0].length];
      if (matched === null || (tail !== undefined && NUMBER_TAIL.test(tail))) {
        throw new ExprError(`malformed number at ${i}`, i);
      }
      tokens.push({ type: 'number', value: Number(matched[0]), index: i });
      i += matched[0].length;
      continue;
    }
    NAME.lastIndex = i;
    const name = NAME.exec(input);
    if (name !== null) {
      tokens.push({ type: 'name', value: name[0], index: i });
      i += name[0].length;
      continue;
    }
    throw new ExprError(`unexpected character '${String.fromCodePoint(input.codePointAt(i))}' at ${i}`, i);
  }
  return tokens;
}

/** Precedence-climbing parser producing the expression tree. */

import { ExprError, tokenize } from './tokenize.js';

const BINARY = {
  '+': { precedence: 1, rightAssociative: false },
  '-': { precedence: 1, rightAssociative: false },
  '*': { precedence: 2, rightAssociative: false },
  '/': { precedence: 2, rightAssociative: false },
  '%': { precedence: 2, rightAssociative: false },
  '^': { precedence: 4, rightAssociative: true },
};
const UNARY_PRECEDENCE = 3;

/**
 * Render a token the way error messages quote it.
 *
 * @param {{ type: string, value: number | string }} token token to quote
 * @returns {string} the token's source text
 */
function display(token) {
  return String(token.value);
}

/**
 * @param {{ tokens: object[], index: number, end: number }} state parser state
 * @returns {object | undefined} the next token, if any
 */
function peek(state) {
  return state.tokens[state.index];
}

/**
 * Build the failure for a token that cannot appear here.
 *
 * @param {{ tokens: object[], index: number, end: number }} state parser state
 * @returns {ExprError} the failure to throw
 */
function unexpected(state) {
  const token = peek(state);
  if (token === undefined) return new ExprError(`unexpected end of input at ${state.end}`, state.end);
  return new ExprError(`unexpected token '${display(token)}' at ${token.index}`, token.index);
}

/**
 * Parse a number, name, call or parenthesised group.
 *
 * @param {{ tokens: object[], index: number, end: number }} state parser state
 * @returns {object} expression node
 */
function parsePrimary(state) {
  const token = peek(state);
  if (token === undefined) throw unexpected(state);

  if (token.type === 'number') {
    state.index += 1;
    return { type: 'number', value: token.value, index: token.index };
  }

  if (token.type === 'name') {
    state.index += 1;
    if (peek(state)?.type !== 'lparen') return { type: 'variable', name: token.value, index: token.index };
    state.index += 1;
    const args = [];
    if (peek(state)?.type === 'rparen') {
      state.index += 1;
      return { type: 'call', name: token.value, args, index: token.index };
    }
    for (;;) {
      args.push(parseExpression(state, 1));
      const separator = peek(state);
      if (separator?.type === 'comma') {
        state.index += 1;
        continue;
      }
      if (separator?.type === 'rparen') {
        state.index += 1;
        return { type: 'call', name: token.value, args, index: token.index };
      }
      throw unexpected(state);
    }
  }

  if (token.type === 'lparen') {
    state.index += 1;
    const inner = parseExpression(state, 1);
    const close = peek(state);
    if (close?.type !== 'rparen') {
      const at = close === undefined ? state.end : close.index;
      throw new ExprError(`missing closing parenthesis at ${at}`, at);
    }
    state.index += 1;
    return inner;
  }

  throw unexpected(state);
}

/**
 * Parse a prefix sign, which binds looser than `^` and tighter than `*`.
 *
 * @param {{ tokens: object[], index: number, end: number }} state parser state
 * @returns {object} expression node
 */
function parseUnary(state) {
  const token = peek(state);
  if (token?.type === 'operator' && (token.value === '-' || token.value === '+')) {
    state.index += 1;
    return { type: 'unary', op: token.value, operand: parseExpression(state, UNARY_PRECEDENCE), index: token.index };
  }
  return parsePrimary(state);
}

/**
 * Parse operators at or above a precedence level.
 *
 * @param {{ tokens: object[], index: number, end: number }} state parser state
 * @param {number} minPrecedence lowest precedence this call may consume
 * @returns {object} expression node
 */
function parseExpression(state, minPrecedence) {
  let left = parseUnary(state);
  for (;;) {
    const token = peek(state);
    if (token?.type !== 'operator') break;
    const operator = BINARY[token.value];
    if (operator === undefined || operator.precedence < minPrecedence) break;
    state.index += 1;
    const next = operator.rightAssociative ? operator.precedence : operator.precedence + 1;
    left = { type: 'binary', op: token.value, left, right: parseExpression(state, next), index: token.index };
  }
  return left;
}

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const state = { tokens: tokenize(input), index: 0, end: typeof input === 'string' ? input.length : 0 };
  const node = parseExpression(state, 1);
  if (state.index < state.tokens.length) throw unexpected(state);
  return node;
}

/**
 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { arity: 1, apply: (args) => Math.abs(args[0]) },
  sqrt: { arity: 1, apply: (args) => Math.sqrt(args[0]) },
  floor: { arity: 1, apply: (args) => Math.floor(args[0]) },
  ceil: { arity: 1, apply: (args) => Math.ceil(args[0]) },
  round: { arity: 1, apply: (args) => Math.round(args[0]) },
  sign: { arity: 1, apply: (args) => Math.sign(args[0]) },
  pow: { arity: 2, apply: (args) => args[0] ** args[1] },
  atan2: { arity: 2, apply: (args) => Math.atan2(args[0], args[1]) },
  min: { arity: null, apply: (args) => Math.min(...args) },
  max: { arity: null, apply: (args) => Math.max(...args) },
};

/**
 * Reject a result that left the finite doubles.
 *
 * @param {number} value computed value
 * @param {{ index: number }} node node the value came from
 * @returns {number} the value itself
 */
function finite(value, node) {
  if (!Number.isFinite(value)) throw new ExprError(`non-finite result at ${node.index}`, node.index);
  return value;
}

/**
 * Resolve a name against the caller's bindings, then the built-in constants.
 *
 * @param {{ name: string, index: number }} node variable node
 * @param {Record<string, unknown>} env caller bindings
 * @returns {number} the bound value
 */
function lookup(node, env) {
  if (env !== null && typeof env === 'object' && Object.hasOwn(env, node.name)) {
    const value = env[node.name];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new ExprError(`variable ${node.name} is not a finite number at ${node.index}`, node.index);
    }
    return value;
  }
  if (Object.hasOwn(CONSTANTS, node.name)) return CONSTANTS[node.name];
  throw new ExprError(`unknown variable: ${node.name} at ${node.index}`, node.index);
}

/**
 * Apply one built-in function after checking its arity.
 *
 * @param {{ name: string, args: object[], index: number }} node call node
 * @param {Record<string, unknown>} env caller bindings
 * @returns {number} the call's result
 */
function call(node, env) {
  if (!Object.hasOwn(FUNCTIONS, node.name)) {
    throw new ExprError(`unknown function: ${node.name} at ${node.index}`, node.index);
  }
  const fn = FUNCTIONS[node.name];
  const args = node.args.map((argument) => evaluateNode(argument, env));
  if (fn.arity === null) {
    if (args.length === 0) {
      throw new ExprError(`function ${node.name} expects at least 1 argument, got 0 at ${node.index}`, node.index);
    }
  } else if (args.length !== fn.arity) {
    const plural = fn.arity === 1 ? 'argument' : 'arguments';
    throw new ExprError(`function ${node.name} expects ${fn.arity} ${plural}, got ${args.length} at ${node.index}`, node.index);
  }
  return finite(fn.apply(args), node);
}

/**
 * Evaluate one node of the expression tree.
 *
 * @param {object} node expression node
 * @param {Record<string, unknown>} env caller bindings
 * @returns {number} the node's value
 */
function evaluateNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;
    case 'variable':
      return lookup(node, env);
    case 'unary': {
      const value = evaluateNode(node.operand, env);
      return finite(node.op === '-' ? -value : value, node);
    }
    case 'binary': {
      const left = evaluateNode(node.left, env);
      const right = evaluateNode(node.right, env);
      if ((node.op === '/' || node.op === '%') && right === 0) {
        throw new ExprError(`division by zero at ${node.index}`, node.index);
      }
      switch (node.op) {
        case '+':
          return finite(left + right, node);
        case '-':
          return finite(left - right, node);
        case '*':
          return finite(left * right, node);
        case '/':
          return finite(left / right, node);
        case '%':
          return finite(left % right, node);
        default:
          return finite(left ** right, node);
      }
    }
    default:
      return call(node, env);
  }
}

/**
 * Evaluate an expression.
 *
 * @param {string} input expression source
 * @param {Record<string, number>} [env] variable bindings, shadowing the built-in constants
 * @returns {number} the finite result
 */
export function evaluate(input, env = {}) {
  return evaluateNode(parse(input), env);
}
